"""The turret click sound is our own, generated by a committed script.

Owner, 2026-10-15 23:30: "Dürbün kulelerini çevirme klik sesi ekleyelim."
* tools/sounds/make_turret_click.py regenerates a byte-identical
  assets/sounds/turret_click.wav (no hand edits, nothing downloaded);
* the file is mono, 16-bit, 44.1 kHz and shorter than 60 ms;
* it is registered as an app asset in pubspec.yaml.
Report: docs/reports/kule_klik_sesi.md.
"""
from __future__ import annotations

import subprocess
import sys
import tempfile
import unittest
import wave
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
SCRIPT = ROOT / "tools" / "sounds" / "make_turret_click.py"
WAV = ROOT / "assets" / "sounds" / "turret_click.wav"


class TurretClickSoundTest(unittest.TestCase):
    def test_script_regenerates_byte_identical_wav(self):
        with tempfile.TemporaryDirectory() as d:
            out = Path(d) / "turret_click.wav"
            subprocess.run(
                [sys.executable, str(SCRIPT), "--out", str(out)],
                check=True,
                capture_output=True,
            )
            self.assertEqual(out.read_bytes(), WAV.read_bytes())

    def test_format_mono_44k1_short(self):
        with wave.open(str(WAV), "rb") as w:
            self.assertEqual(w.getnchannels(), 1)
            self.assertEqual(w.getsampwidth(), 2)
            self.assertEqual(w.getframerate(), 44100)
            seconds = w.getnframes() / w.getframerate()
            frames = w.readframes(w.getnframes())
        self.assertLess(seconds, 0.060)
        self.assertGreaterEqual(seconds, 0.025)
        self.assertLessEqual(seconds, 0.040)
        samples = memoryview(frames).cast("h")
        peak = max(abs(s) for s in samples)
        # Moderate: about -6 dBFS, never clipping; ends in silence.
        self.assertLess(peak, 32767 * 0.55)
        self.assertGreater(peak, 32767 * 0.30)
        self.assertEqual(samples[-1], 0)

    def test_registered_as_asset(self):
        pubspec = (ROOT / "pubspec.yaml").read_text(encoding="utf-8")
        self.assertIn("- assets/sounds/turret_click.wav", pubspec)

    def test_script_uses_no_network(self):
        src = SCRIPT.read_text(encoding="utf-8")
        for marker in ("urllib", "requests", "http", "socket"):
            self.assertNotIn(marker, src)


if __name__ == "__main__":
    unittest.main()
